// @name Transit departures (GTFS-Realtime, any country)
// @background #0f172a
// @refresh 60
// The next departures from one or two stops as a station board, from any
// agency in the world that publishes a GTFS-Realtime TripUpdates feed: the
// frame downloads the agency's protobuf feed itself and keeps only the stops
// asked for (gtfsrt.ts, feed.ts). A feed has times but no names: the Lines
// setting gives each route its name, color and destinations. The last good
// departures are kept on disk (the private `board` field), and an error says
// what went wrong.
import { due, loadBoard, namesOf, saveBoard, stopOf, type Board } from './board'
import { headersOf, readFeed } from './feed'
import { parseLines } from './gtfsrt'
import { drawBoard, setupCard } from './ui'

const TITLE = 'Transit departures'

// Since when a feed has been coming in, on this interpreter (a Pi, an ESP32
// that stays awake): no second request while one streams.
let streamingSince = 0

// Asks the feed again. Where nothing pumps promises (a board that sleeps,
// the preview) it is all read within this call; on a Pi and an ESP32 that
// stays awake the pieces come between renders, and the scene draws itself
// again when the last one is in.
function refresh(app: FrameOSApp, key: string, kept: Board | null, now: number, url: string, stopIds: string[][]): Board & { loading?: boolean } {
  const base: Board = kept || { key, at: 0, tried: 0, stops: [], error: '' }
  if (streamingSince && now - streamingSince < 90 * 1000) return { ...base, loading: true }
  streamingSince = now
  let inCall = true
  let answered: Board | null = null
  const lines = parseLines(String(app.state.lines ?? ''))
  readFeed(app, url, headersOf(String(app.state.feedHeader ?? '')), stopIds, lines, now, (scan, error) => {
    streamingSince = 0
    const when = Date.now()
    const board: Board = scan
      ? {
          key,
          at: when,
          tried: when,
          error: '',
          feedTime: scan.feedTime * 1000,
          // A feed names no stop: the first id, until the stop is given a name.
          stops: scan.stops.map((s, i) => ({ name: `Stop ${stopIds[i][0]}${stopIds[i].length > 1 ? ` +${stopIds[i].length - 1}` : ''}`, list: s.list.slice(0, 24) })),
        }
      : { ...base, key, tried: when, error }
    saveBoard(board)
    if (inCall) answered = board
    else frameos.dispatch('render')
  })
  inCall = false
  if (answered) return answered
  // Coming in between renders: the last good ones until then.
  const waiting: Board = { ...base, key, tried: now }
  saveBoard(waiting)
  return { ...waiting, loading: true }
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const url = String(app.state.feedUrl ?? '').trim()
  if (!/^https?:\/\//.test(url)) {
    return setupCard(app, context, TITLE, "Add the address of a GTFS-Realtime TripUpdates feed in the scene settings: any agency's, anywhere in the world (they are listed on mobilitydatabase.org).")
  }
  const stops = [stopOf(app.state.stop), stopOf(app.state.stop2)].filter((stop) => stop.query)
  if (!stops.length) {
    return setupCard(app, context, TITLE, "Add a stop in the scene settings: the stop_id the feed uses, from the agency's GTFS stops.txt, a few with commas.")
  }
  const queries = stops.map((stop) => stop.query)
  const key = `${queries.join('/')}|${url}|${String(app.state.lines ?? '')}`
  const now = Date.now()
  let board: (Board & { loading?: boolean }) | null = loadBoard(app, key)
  if (due(board, now)) board = refresh(app, key, board, now, url, queries.map(namesOf))
  return drawBoard(app, context, { provider: 'GTFS-Realtime', title: TITLE, labels: stops.map((stop) => stop.label), queries, board })
}

