// GTFS-Realtime TripUpdates, read as the feed streams in.
//
// A feed is one protobuf FeedMessage for a whole network: 0.6 to 1.1 MB for a
// city (MBTA, SEPTA, Helsinki, Halifax), 4 to 15 MB for a country. A frame
// never holds it: the body comes in pieces (fetch's onChunk), each piece is
// walked entity by entity and dropped, and only the departures at the stops
// asked for are kept. An entity is decoded only when one of those stop ids
// is in it, which a native indexOf finds; the others are stepped over by
// their length. So the work is a few reads per entity, not per byte.
//
// The pieces are text. The runtime reads a body that is not UTF-8 as
// Windows-1252, one character a byte, from its first piece on (protobuf is
// never UTF-8 for long), so every byte comes back: below 256 a character is
// its byte, and the 27 characters Windows-1252 puts at 0x80 to 0x9f are
// turned back here (BACK). A body read whole with httpRequest's base64 is
// one character a byte already.
//
// The fields read (gtfs-realtime.proto):
//   FeedMessage   1 header, 2 entity
//   FeedHeader    3 timestamp
//   FeedEntity    2 is_deleted, 3 trip_update
//   TripUpdate    1 trip, 2 stop_time_update, 5 delay, 6 trip_properties
//   TripDescriptor 4 schedule_relationship, 5 route_id, 6 direction_id
//   TripProperties 5 trip_headsign
//   StopTimeUpdate 2 arrival, 3 departure, 4 stop_id, 5 schedule_relationship
//   StopTimeEvent  1 delay, 2 time, 4 scheduled_time
import type { Departure } from './board'

export type LineInfo = { label: string; color: string; to: string[] }

// Windows-1252's characters for bytes 0x80 to 0x9f, back to the bytes.
const BACK: Record<number, number> = {
  0x20ac: 0x80, 0x201a: 0x82, 0x0192: 0x83, 0x201e: 0x84, 0x2026: 0x85, 0x2020: 0x86, 0x2021: 0x87,
  0x02c6: 0x88, 0x2030: 0x89, 0x0160: 0x8a, 0x2039: 0x8b, 0x0152: 0x8c, 0x017d: 0x8e,
  0x2018: 0x91, 0x2019: 0x92, 0x201c: 0x93, 0x201d: 0x94, 0x2022: 0x95, 0x2013: 0x96, 0x2014: 0x97,
  0x02dc: 0x98, 0x2122: 0x99, 0x0161: 0x9a, 0x203a: 0x9b, 0x0153: 0x9c, 0x017e: 0x9e, 0x0178: 0x9f,
}

// A character no Windows-1252 byte becomes: the piece was read as UTF-8.
const NOT_1252 = /[^\x00-\xff\u0152\u0153\u0160\u0161\u0178\u017d\u017e\u0192\u02c6\u02dc\u2013\u2014\u2018-\u201a\u201c-\u201e\u2020-\u2022\u2026\u2030\u2039\u203a\u20ac\u2122]/

// A piece the runtime read as UTF-8 (a first piece that happened to be
// valid UTF-8): its bytes again, one character each.
function utf8Bytes(text: string): string {
  const bytes = new TextEncoder().encode(text)
  let out = ''
  for (let i = 0; i < bytes.length; i += 4096) {
    out += String.fromCharCode.apply(null, Array.from(bytes.subarray(i, i + 4096)))
  }
  return out
}

// Bytes of the feed as text: a route id or a headsign, which may be UTF-8.
function text(from: number, to: number): string {
  const raw = S.slice(from, to)
  if (!/[^\x00-\x7f]/.test(raw)) return raw
  const bytes = new Uint8Array(raw.length)
  for (let i = 0; i < raw.length; i++) {
    const c = raw.charCodeAt(i)
    bytes[i] = c < 256 ? c : BACK[c] ?? 0x3f
  }
  return new TextDecoder().decode(bytes)
}

// A stop id as the feed's bytes, to be found in them.
function idBytes(id: string): string {
  return /[^\x00-\x7f]/.test(id) ? utf8Bytes(id) : id
}

// The reader: S the bytes, P where it is, E where it must stop.
let S = ''
let P = 0
let E = 0

function byte(): number {
  const c = S.charCodeAt(P++)
  return c < 256 ? c : BACK[c] ?? 0
}

// A varint as a number (exact to 2^53: times, lengths, ids). Past E, P is
// left past E, which is how a caller learns the piece ended inside it.
function varint(): number {
  let value = 0
  let scale = 1
  for (;;) {
    if (P >= E) {
      P = E + 1
      return 0
    }
    const c = byte()
    value += (c & 127) * scale
    if (c < 128) return value
    scale *= 128
  }
}

// An int32 varint (a delay): its low 32 bits, signed. A negative one is ten
// bytes long.
function int32(): number {
  let low = 0
  let shift = 0
  for (;;) {
    if (P >= E) return low | 0
    const c = byte()
    if (shift < 32) low |= (c & 127) << shift
    shift += 7
    if (c < 128) return low | 0
  }
}

// Steps over a field of this wire type; false when the piece ends inside it.
function skip(wire: number): boolean {
  if (wire === 0) varint()
  else if (wire === 1) P += 8
  else if (wire === 2) {
    const n = varint()
    if (P <= E) P += n
  } else if (wire === 5) P += 4
  else throw new Error('not a GTFS-Realtime feed (an unknown field type)')
  return P <= E
}

type Event = { time: number; delay: number | null; scheduled: number }

function stopEvent(from: number, to: number): Event {
  const ev: Event = { time: 0, delay: null, scheduled: 0 }
  P = from
  E = to
  while (P < E) {
    const tag = varint()
    const field = tag >>> 3
    const wire = tag & 7
    if (field === 1 && wire === 0) ev.delay = int32()
    else if (field === 2 && wire === 0) ev.time = varint()
    else if (field === 4 && wire === 0) ev.scheduled = varint()
    else skip(wire)
  }
  return ev
}

export type Scan = {
  stops: { ids: string[]; list: Departure[] }[]
  lines: Record<string, LineInfo>
  now: number
  feedTime: number
  entities: number
  bytes: number
}

export function lineOf(lines: Record<string, LineInfo>, route: string): LineInfo {
  return lines[route] || { label: route, color: '', to: [] }
}

// One trip's update: the departures it makes from the stops asked for.
function tripUpdate(scan: Scan, from: number, to: number) {
  let route = ''
  let direction = -1
  let canceled = false
  let headsign = ''
  let tripDelay: number | null = null
  const updates: number[] = []
  P = from
  E = to
  while (P < E) {
    const tag = varint()
    const field = tag >>> 3
    const wire = tag & 7
    if (wire === 2 && (field === 1 || field === 2 || field === 6)) {
      const n = varint()
      const start = P
      P += n
      if (field === 2) updates.push(start, P)
      else {
        // The trip, or its properties: read them here and come back.
        const back = P
        P = start
        E = back
        while (P < E) {
          const t = varint()
          const f = t >>> 3
          const w = t & 7
          if (field === 1 && f === 5 && w === 2) {
            const len = varint()
            route = text(P, P + len)
            P += len
          } else if (field === 1 && f === 6 && w === 0) direction = varint()
          else if (field === 1 && f === 4 && w === 0) canceled = varint() === 3
          else if (field === 6 && f === 5 && w === 2) {
            const len = varint()
            headsign = text(P, P + len)
            P += len
          } else skip(w)
        }
        P = back
        E = to
      }
    } else if (field === 5 && wire === 0) tripDelay = int32()
    else skip(wire)
  }
  const line = lineOf(scan.lines, route)
  const toward = headsign || (direction >= 0 ? line.to[direction] || line.to[0] || '' : line.to[0] || '')
  const last = updates.length - 2
  for (let u = 0; u < updates.length; u += 2) {
    // The stop's id first: most updates are of other stops.
    P = updates[u]
    E = updates[u + 1]
    let stop = ''
    let arrival = -1
    let departure = -1
    let skipped = false
    while (P < E) {
      const tag = varint()
      const field = tag >>> 3
      const wire = tag & 7
      if (wire === 2 && (field === 2 || field === 3 || field === 4)) {
        // An event is kept as where its length starts, and read only for a stop asked for.
        const lengthAt = P
        const n = varint()
        if (field === 4) stop = S.slice(P, P + n)
        else if (field === 2) arrival = lengthAt
        else departure = lengthAt
        P += n
      } else if (field === 5 && wire === 0) skipped = varint() === 1
      else skip(wire)
    }
    if (!stop) continue
    for (const board of scan.stops) {
      if (board.ids.indexOf(stop) < 0) continue
      // A trip that ends here makes no departure from here.
      if (u === last && departure < 0 && updates.length > 2) continue
      const at = departure >= 0 ? departure : arrival
      if (at < 0) continue
      P = at
      E = updates[u + 1]
      const n = varint()
      const ev = stopEvent(P, P + n)
      if (!ev.time) continue
      let delay = ev.scheduled ? ev.time - ev.scheduled : ev.delay
      if (delay === null) delay = tripDelay
      if (ev.time * 1000 < scan.now - 30000) continue
      board.list.push({
        line: line.label,
        color: line.color,
        text: '',
        to: toward,
        at: ev.time * 1000,
        live: true,
        delay,
        gone: canceled || skipped,
        where: '',
      })
    }
  }
}

function entity(scan: Scan, from: number, to: number) {
  let update = -1
  let updateEnd = -1
  let deleted = false
  P = from
  E = to
  while (P < E) {
    const tag = varint()
    const field = tag >>> 3
    const wire = tag & 7
    if (field === 3 && wire === 2) {
      const n = varint()
      update = P
      updateEnd = P + n
      P += n
    } else if (field === 2 && wire === 0) deleted = varint() !== 0
    else skip(wire)
  }
  if (update >= 0 && !deleted) tripUpdate(scan, update, updateEnd)
}

function header(scan: Scan, from: number, to: number) {
  P = from
  E = to
  while (P < E) {
    const tag = varint()
    if (tag >>> 3 === 3 && (tag & 7) === 0) scan.feedTime = varint()
    else skip(tag & 7)
  }
}

// The feed, a piece at a time: push() each piece, then end().
export class FeedScanner {
  scan: Scan
  rest = ''
  started = false
  needles: string[] = []

  constructor(stops: string[][], lines: Record<string, LineInfo>, now: number) {
    // The ids as the feed's bytes, the way a stop_id is compared.
    const byteIds = stops.map((ids) => ids.filter(Boolean).map(idBytes))
    this.scan = { stops: byteIds.map((ids) => ({ ids, list: [] })), lines, now, feedTime: 0, entities: 0, bytes: 0 }
    // A stop id in a StopTimeUpdate is field 4, length-delimited: the tag
    // byte 0x22 ('"'), its length, then its bytes.
    for (const ids of byteIds) {
      for (const id of ids) {
        if (id.length < 128) this.needles.push('"' + String.fromCharCode(id.length) + id)
      }
    }
  }

  nextMatch(from: number): number {
    let best = -1
    for (const needle of this.needles) {
      const at = S.indexOf(needle, from)
      if (at >= 0 && (best < 0 || at < best)) best = at
    }
    return best
  }

  // A piece of text as fetch's onChunk hands it over (binary: true for one
  // that is one character a byte already).
  push(piece: string, binary = false) {
    if (!piece) return
    const bytes = binary || !NOT_1252.test(piece) ? piece : utf8Bytes(piece)
    this.scan.bytes += bytes.length
    S = this.rest ? this.rest + bytes : bytes
    this.rest = ''
    P = 0
    E = S.length
    if (!this.started) {
      // A FeedMessage starts with its header, field 1. Anything else is
      // a page, an error in JSON or another format.
      const first = S.charCodeAt(0)
      if (first !== 0x0a) {
        const said = S.slice(0, 120).replace(/\s+/g, ' ').trim()
        throw new Error(first === 0x3c || first === 0x7b ? `not a GTFS-Realtime feed: "${said.slice(0, 80)}"` : 'not a GTFS-Realtime feed')
      }
      this.started = true
    }
    let next = this.nextMatch(0)
    for (;;) {
      if (P >= S.length) break
      const start = P
      E = S.length
      const tag = varint()
      if (P > E) {
        P = start
        break
      }
      const field = tag >>> 3
      const wire = tag & 7
      if (wire !== 2) {
        if (!skip(wire)) {
          P = start
          break
        }
        continue
      }
      const n = varint()
      if (P > E || P + n > E) {
        // The piece ends inside this one: it is read with the next.
        P = start
        break
      }
      const body = P
      const end = P + n
      if (field === 2) {
        this.scan.entities++
        if (next >= 0 && next < end) {
          entity(this.scan, body, end)
          next = this.nextMatch(end)
        }
      } else if (field === 1) header(this.scan, body, end)
      P = end
    }
    if (P < S.length) {
      this.rest = S.slice(P)
      // An entity this long is no transit feed's.
      if (this.rest.length > 4 * 1024 * 1024) throw new Error('not a GTFS-Realtime feed (an entity of 4 MB)')
    }
    S = ''
  }

  end(): Scan {
    if (!this.started) throw new Error('the feed was empty')
    for (const board of this.scan.stops) board.list.sort((a, b) => a.at - b.at)
    return this.scan
  }
}

// "Red | Red Line | #DA291C | Ashmont/Braintree | Alewife": a route id, the
// name to show, its color and where it goes in direction 0 and 1. Lines that
// do not say a part leave it out; # starts a comment.
export function parseLines(text: string): Record<string, LineInfo> {
  const lines: Record<string, LineInfo> = {}
  for (const raw of String(text || '').split('\n')) {
    const row = raw.trim()
    if (!row || row[0] === '#') continue
    const parts = row.split('|').map((part) => part.trim())
    const id = parts[0]
    if (!id) continue
    const color = /^#?[0-9a-fA-F]{6}$/.test(parts[2] || '') ? parts[2].replace('#', '').toUpperCase() : ''
    lines[id] = { label: parts[1] || id, color, to: [parts[3] || '', parts[4] || ''] }
  }
  return lines
}

