// Getting a GTFS-Realtime feed to the scanner (gtfsrt.ts).
//
// Where the runtime hands a body over in pieces (fetch.chunks, FrameOS
// 2026.11.15+), the feed streams through and is never held: any size works,
// on an ESP32 too, at the cost of downloading it all every refresh (a city's
// feed is 0.2 to 1 MB on the wire, gzipped where the server offers it).
// Where nothing pumps promises (a board that sleeps, the preview) every piece
// comes inside the fetch() call and done() is called before it returns; on a
// Pi and an ESP32 that stays awake the pieces come between renders and done()
// later.
//
// An older runtime reads the body whole (httpRequest's base64): fine on a Pi,
// and on an ESP32 only for a small feed, which is checked first.
import { FeedScanner, type LineInfo, type Scan } from './gtfsrt'

export type FeedDone = (scan: Scan | null, error: string) => void

// The largest feed an ESP32 without streaming reads whole: its bytes, the
// base64 of them and the string they decode to are all held at once.
const WHOLE_ON_A_BOARD = 512 * 1024

// "x-api-key: abc" as a header.
export function headersOf(text: string): Record<string, string> {
  const headers: Record<string, string> = {}
  const line = String(text || '').trim()
  const at = line.indexOf(':')
  if (at > 0) headers[line.slice(0, at).trim()] = line.slice(at + 1).trim()
  return headers
}

const message = (e: any) => String(e?.message || e || 'failed')

export function readFeed(
  app: FrameOSApp,
  url: string,
  headers: Record<string, string>,
  stops: string[][],
  lines: Record<string, LineInfo>,
  now: number,
  done: FeedDone,
) {
  const scanner = new FeedScanner(stops, lines, now)
  let finished = false
  const finish = (scan: Scan | null, error: string) => {
    if (finished) return
    finished = true
    done(scan, error)
  }
  const streams = typeof fetch === 'function' && (fetch as any).chunks === true
  if (streams) {
    fetch(url, {
      headers,
      timeoutMs: 30000,
      chunkBytes: 16384,
      onChunk(text: string, info: any) {
        if (finished) return false
        if (info.status < 200 || info.status >= 300) {
          finish(null, `HTTP ${info.status}`)
          return false
        }
        try {
          if (text) scanner.push(text)
          if (info.done) {
            if (info.error) finish(null, String(info.error))
            else finish(scanner.end(), '')
          }
        } catch (e) {
          finish(null, message(e))
          return false
        }
        return true
      },
    } as any).then(
      () => finish(null, 'the feed ended early'),
      (e: any) => finish(null, message(e)),
    )
    return
  }
  try {
    if (app.frame.embedded) {
      // Ask how big it is before holding it whole.
      const head = frameos.httpRequest(url, { method: 'HEAD', headers, timeoutMs: 15000 })
      const size = Number(head?.headers?.['content-length'] || 0)
      if (!(size > 0) || size > WHOLE_ON_A_BOARD) {
        const said = size > 0 ? `${Math.round(size / 1024)} KB` : 'of a size it does not say'
        throw new Error(`this feed is ${said}, too big for this frame to read at once: FrameOS 2026.11.15 or later reads it in pieces`)
      }
    }
    if (typeof atob !== 'function') throw new Error('reading a GTFS-Realtime feed needs FrameOS 2026.11.12 or later')
    const reply = frameos.httpRequest(url, { headers, base64: true, timeoutMs: 30000 })
    if (!reply || reply.error) throw new Error(reply?.error || 'no answer')
    if (reply.status < 200 || reply.status >= 300) throw new Error(`HTTP ${reply.status}`)
    scanner.push(atob(reply.bodyBase64 || ''), true)
    finish(scanner.end(), '')
  } catch (e) {
    finish(null, message(e))
  }
}

