  })
})

describe('the scene on a GTFS-Realtime feed', () => {
  const realFetch = globalThis.fetch
  afterEach(() => {
    globalThis.fetch = realFetch
  })
  const STATE = { stop: 'Home = 70076', feedUrl: 'https://example.com/tu.pb', lines: 'Red | Red | #DA291C | Ashmont | Alewife' }

  it('streams the feed where the runtime hands it over in pieces', () => {
    const fake: any = (url: string, init: any) => {
      expect(url).toBe('https://example.com/tu.pb')
      const info: any = { status: 200, headers: {}, done: false, bytes: 0 }
      for (const piece of pieces(as1252(FEED), 16)) init.onChunk(piece, info)
      info.done = true
      init.onChunk('', info)
      return Promise.resolve({ ok: true })
    }
    fake.chunks = true
    globalThis.fetch = fake
    const app = makeApp({ state: STATE })
    const tree = at(NOW, () => get(app, makeContext()))
    expect(app.state.board.stops[0].list.map((d: any) => [d.line, d.to, d.color])).toEqual([
      ['Red', 'Alewife', 'DA291C'],
      ['Orange', '', ''],
      ['Red', 'Alewife', 'DA291C'],
    ])
    const said = textOf(tree)
    expect(said).toContain('Home')
    expect(said).toContain('Canceled')
  })

  it('draws the last ones while the feed comes in between renders, then again', () => {
    let onChunk: any = null
    const fake: any = (url: string, init: any) => {
      onChunk = init.onChunk
      return new Promise(() => {})
    }
    fake.chunks = true
    globalThis.fetch = fake
    const dispatch = mock.dispatch(() => undefined)
    const app = makeApp({ state: STATE })
    const tree = at(NOW, () => get(app, makeContext()))
    expect(textOf(tree)).toContain('Loading departures from GTFS-Realtime')
    at(NOW + 2000, () => {
      onChunk(as1252(FEED), { status: 200, headers: {}, done: false })
      onChunk('', { status: 200, headers: {}, done: true })
    })
    expect(dispatch.calls).toEqual([['render']])
    expect(app.state.board.stops[0].list.length).toBe(3)
  })

  it('reads a feed whole on a runtime without pieces, and a big one not on a board', () => {
    const fake: any = () => Promise.reject(new Error('not this way'))
    globalThis.fetch = fake
    const http = mock.httpRequest((url: string, options: any) => {
      if (options.method === 'HEAD') return { status: 200, headers: { 'content-length': '2000000' }, body: '' }
      expect(options.base64).toBe(true)
      return { status: 200, headers: {}, bodyBase64: btoa(FEED) }
    })
    const pi = makeApp({ state: STATE })
    at(NOW, () => get(pi, makeContext()))
    expect(pi.state.board.error).toBe('')
    expect(pi.state.board.stops[0].list.length).toBe(3)
    const board = makeApp({ state: STATE, frame: { embedded: true } })
    at(NOW, () => get(board, makeContext()))
    expect(board.state.board.error).toContain('this feed is 1953 KB, too big for this frame to read at once')
    expect(http.calls.filter((call: any) => call[1].method === 'HEAD').length).toBe(1)
  })
})

